    getProductosPenientesEntrega(productos) {
        return {
            table: {
                widths: ["10%", "10%", "80%"],
                alignment: 'center',
                body: [
                    [{
                            text: 'Cant.',
                            style: 'tableHeader2',
                            alignment: 'center'
                        },
                        {
                            text: 'Unid.',
                            style: 'tableHeader2',
                            alignment: 'center'
                        },
                        {
                            text: 'Producto',
                            style: 'tableHeader2',
                            alignment: 'center'
                        }
                    ],
                    ...productos.map(ed => {
                        return [{ text: ed.cantM2, alignment: 'center' }, { text: ed.producto.UNIDAD, fontSize: 8, alignment: "center" }, ed.producto.PRODUCTO];
                    }),
                ]
            }
        };
    }
    getProductosVendidos(productos) {
        let productos2 = [];
        productos.forEach(element => {
            if (element.pedir == true)
                element.tipoDocumentoVenta = "P";
            else
                element.tipoDocumentoVenta = "E";
            productos2.push(element);
        });
        return {
            relativePosition: {
                x: 0,
                y: 0,
            },
            table: {
                headerRows: 1,
                widths: ["8%", "6%", "55%", "6%", "10%", "10%"],
                alignment: 'center',
                body: [
                    [{
                            text: 'CANT',
                            style: 'tableHeader2',
                            alignment: 'center'
                        },
                        {
                            text: 'UNID',
                            style: 'tableHeader2',
                            alignment: 'center'
                        },
                        {
                            text: 'DESCRIPCION',
                            style: 'tableHeader2',
                            alignment: 'center'
                        },
                        {
                            text: 'EST',
                            style: 'tableHeader2',
                            alignment: 'center'
                        },
                        {
                            text: 'P.UNIT',
                            style: 'tableHeader2',
                            alignment: 'center'
                        },
                        {
                            text: 'TOTAL',
                            style: 'tableHeader2',
                            alignment: 'center'
                        },
                    ],
                    ...productos2.map(ed => {
                        return [{ text: ed.cantidad, alignment: 'center', fontSize: 8 },
                            { text: ed.producto.UNIDAD, fontSize: 8, alignment: "center" },
                            { text: ed.producto.PRODUCTO, fontSize: 8 },
                            { text: ed.entregar ? "ENT" : "PTE", fontSize: 8, alignment: "center" },
                            { text: ed.precio_venta.toFixed(2), fontSize: 8, alignment: "center" },
                            { text: ed.total.toFixed(2), alignment: "right", fontSize: 8 }];
                    }),
                ]
            },
            layout: 'headerLineOnly',
        };
    }
